INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102119', 'Điện chiếu sáng bị hư tại đường Đà Sơn 4', 'Hiện tại trên đường Đà Sơn 4, phường Hòa Khánh có 2 trụ đèn chiếu sáng bị hư không sáng. Kính đề nghị cơ quan chức năng kiểm tra và khắc phục để đảm bảo an toàn giao thông.', 'Đường Đà Sơn 4, Hòa Khánh', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-LLC' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Liên Chiểu', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.072481, 108.150905);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102094', 'Bóng đèn chiếu sáng bị hỏng tại K162 đường Bình Kỳ', 'Tại giữa đường kiệt 162 đường Bình Kỳ, phường Ngũ Hành Sơn có một trụ đèn chiếu sáng số hiệu 8 bị cháy bóng. Mong cơ quan chức năng sớm thay thế.', 'K162 Bình Kỳ', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-NHS' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Ngũ Hành Sơn', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.027557, 108.246925);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102073', 'Điện chiếu sáng bị hỏng tại khu vực An Ngãi Tây 1', 'Tại khu vực An Ngãi Tây 1, đoạn cách trụ sở UBND xã Hòa Sơn (cũ) khoảng 80m theo hướng Bắc có đèn đường bị hỏng mấy ngày nay. Đề nghị sửa chữa.', 'An Ngãi Tây 1, Hòa Sơn', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-HV' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Hòa Vang', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 15.991785, 108.122899);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102184', 'Xây dựng lấn chiếm vỉa hè tại ngã tư Lương Trúc Đàm', 'Tôi có phản ánh về việc lấn chiếm vỉa hè tại khu vực ngã tư đường Lương Trúc Đàm và Nam Trân để vật liệu xây dựng cản trở người đi bộ.', 'Ngã tư Lương Trúc Đàm - Nam Trân', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-TK' LIMIT 1), (SELECT id FROM categories WHERE code = 'CONSTRUCTION' LIMIT 1), 'Thanh Khê', 'CONSTRUCTION', 'Xây dựng', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.063360, 108.200247);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102568', 'MTĐT_Thu gom rác tại khu vực 72-78 Trần Thủ Độ', 'Tại khu vực từ số 72 đến số 78 đường Trần Thủ Độ, phường Cẩm Lệ, rác sinh hoạt đã 3 ngày chưa được thu gom bốc mùi hôi thối.', '72-78 Trần Thủ Độ', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-CL' LIMIT 1), (SELECT id FROM categories WHERE code = 'ENVIRONMENT' LIMIT 1), 'Cẩm Lệ', 'ENVIRONMENT', 'Môi trường', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.022976, 108.201577);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102265', 'MTĐT_Không thu gom rác tại tuyến đường Thanh Tân', 'Cả tuyến đường Thanh Tân phường Thanh Khê đã 3 ngày rồi chưa có người thu gom rác. Hiện rác nay nhiều quá tràn ra cả mặt đường.', 'Tuyến đường Thanh Tân', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-TK' LIMIT 1), (SELECT id FROM categories WHERE code = 'ENVIRONMENT' LIMIT 1), 'Thanh Khê', 'ENVIRONMENT', 'Môi trường', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.060127, 108.192629);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-101972', 'Thi công gây bụi tại đường Trưng Nữ Vương phường Bình Thuận', 'Tuyến đường Trưng Nữ Vương (đoạn từ Trần Đại Nghĩa đến Phan Bội Châu) đang thi công làm bụi bay mù mịt vào nhà dân, không tưới nước thường xuyên.', 'Đường Trưng Nữ Vương', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-HC' LIMIT 1), (SELECT id FROM categories WHERE code = 'CONSTRUCTION' LIMIT 1), 'Hải Châu', 'CONSTRUCTION', 'Xây dựng', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.042422, 108.219316);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102151', 'Lấn chiếm vỉa hè tại 219 Nguyễn Văn Linh', 'Hiện tại, quán này mình đã thấy bán rất lâu và lấn chiếm vỉa hè gây mất cảnh quan đô thị, bày bàn ghế cho khách ngồi chắn hết lối đi.', '219 Nguyễn Văn Linh', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-HC' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Hải Châu', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.043769, 108.218654);
