INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102125', 'MTĐT_Không thu gom rác tuyến đường Bàu Năng 5', 'Kính đề nghị cơ quan chức năng kiểm tra tình trạng chậm thu gom rác tại khu vực đường Bàu Năng 5, khiến rác bốc mùi hôi thối lan vào nhà dân.', 'Bàu Năng 5', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-LLC' LIMIT 1), (SELECT id FROM categories WHERE code = 'ENVIRONMENT' LIMIT 1), 'Liên Chiểu', 'ENVIRONMENT', 'Môi trường', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.073780, 108.145218);
