INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-99670', 'Vỉa hè bị hư hỏng tại đường Ngô Quyền', 'Vỉa hè bị hư hỏng tại tuyến đường Ngô Quyền, khu vực giao giữa đường Ngô Quyền và Đường số 1 (KCN An Đồn). Gạch lót bị bong tróc toàn bộ.', 'Giao Ngô Quyền và Đường số 1', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-ST' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Sơn Trà', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.083853, 108.238900);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-101912', 'Ô nhiễm tiếng ồn tại 67 Doãn Khuê', 'Tôi xin tiếp tục phản ánh về tình trạng của quán cà phê tại địa chỉ 67 đường Doãn Khuê, Hòa Cường mở nhạc xập xình cả ngày.', '67 Doãn Khuê', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-HC' LIMIT 1), (SELECT id FROM categories WHERE code = 'PUBLIC_SECURITY' LIMIT 1), 'Hải Châu', 'PUBLIC_SECURITY', 'An ninh trật tự', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.051564, 108.220551);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-101934', 'Công ty chế biến trà sữa hoạt động gây ô nhiễm', 'Tôi phản ánh việc Công ty chế biến trà sữa đang thuê mặt bằng ở 196-198 Hà Huy Giáp xả thải nước chưa qua xử lý thẳng ra cống công cộng.', '196-198 Hà Huy Giáp', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-CL' LIMIT 1), (SELECT id FROM categories WHERE code = 'ENVIRONMENT' LIMIT 1), 'Cẩm Lệ', 'ENVIRONMENT', 'Môi trường', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.022579, 108.198546);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-101953', 'Dây điện thoại thòng xuống đường ngay ngã tư Lê Đình Dương', 'Tại khu vực ngã tư Lê Đình Dương – Hoàng Diệu (trước số nhà 130 và 137), dây cáp viễn thông thòng sát mặt đường rất dễ quấn vào cổ người đi xe máy.', 'Ngã tư Lê Đình Dương - Hoàng Diệu', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-HC' LIMIT 1), (SELECT id FROM categories WHERE code = 'URBAN_INFRASTRUCTURE' LIMIT 1), 'Hải Châu', 'URBAN_INFRASTRUCTURE', 'Hạ tầng đô thị', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.044389, 108.216924);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102049', 'Đề nghị xử lý tình trạng đổ xà bần, rác thải trước khu dân cư', 'Tôi xin phản ánh tình trạng đổ xà bần, phế thải xây dựng và rác thải không đúng nơi quy định tại khu vực bãi đất trống đường Lê Văn Hiến.', 'Đường Lê Văn Hiến', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-NHS' LIMIT 1), (SELECT id FROM categories WHERE code = 'ENVIRONMENT' LIMIT 1), 'Ngũ Hành Sơn', 'ENVIRONMENT', 'Môi trường', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.027468, 108.244430);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102091', 'Xe ô tô đậu đỗ tại 131 Nguyễn Hồng Ánh cản trở giao thông', 'Tại 131 Nguyễn Hồng Ánh, phường Hòa Xuân có xe ô tô đậu đỗ tại đây quá lâu dẫn đến nhiều khó khăn cho các phương tiện khác lưu thông.', '131 Nguyễn Hồng Ánh', 'SUBMITTED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-CL' LIMIT 1), (SELECT id FROM categories WHERE code = 'TRAFFIC' LIMIT 1), 'Cẩm Lệ', 'TRAFFIC', 'Giao thông', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.023865, 108.200747);
INSERT INTO feedbacks (tracking_code, title, description, address_details, status, submitted_at, created_at, updated_at, ward_id, category_id, ward_name, category_code, category_name, citizen_id, receiver_type, priority, latitude, longitude) VALUES ('DN-102258', 'Tình trạng lấn chiếm vỉa hè gây mất trật tự tại 02 Tây Sơn', 'Tại khu vực số 02 Tây Sơn, chợ Non Nước, phường Ngũ Hành Sơn, có hộ từ miền Tây ra thuê lại quầy bán trái cây lấn chiếm toàn bộ lối đi.', '02 Tây Sơn', 'RESOLVED', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, (SELECT id FROM wards WHERE ward_code = 'DN-NHS' LIMIT 1), (SELECT id FROM categories WHERE code = 'PUBLIC_SECURITY' LIMIT 1), 'Ngũ Hành Sơn', 'PUBLIC_SECURITY', 'An ninh trật tự', (SELECT id FROM users LIMIT 1), 'WARD_STAFF', 'MEDIUM', 16.031390, 108.251578);
